/* ============================================================ ports ===== */

/**
 * A forwarded service as the source device's agent describes it
 * (PortDetails, server/lib/ports.js): one process, named from its project's
 * package.json, with the framework it depends on.
 */
interface PortService {
  port: number;
  /** The project's package name (a "project name" identity). */
  name: string;
  /** The framework from the project's dependencies, if one is known. */
  kind: string | null;
  process: string;
  pid: number;
  /** Seconds since the process started. */
  uptime: number;
}

// The Devbox runs the API (Hono) and the web app's Next.js dev server.
const FORWARDED: PortService[] = [
  { port: 3000, name: "web", kind: "Next.js", process: "node", pid: 48213, uptime: 2820 },
  { port: 8787, name: "api", kind: "Hono", process: "node", pid: 48127, uptime: 11_520 },
];

// The docs' VitePress dev server, started on the Devbox while the panel is
// open; VitePress is no framework the agent names, so the row has no kind.
const DOCS_SERVER: PortService = { port: 5173, name: "docs", kind: null, process: "node", pid: 48390, uptime: 6 };

// The loop: forwarding runs automatically, the panel polls every 4s (the
// app's POLL_MS), so a service started on the Devbox shows up on the next
// poll, forwarded, and leaves again when it stops.
const PORTS_REST_MS = 2600;
const PORTS_UP_MS = 5200;
const PORTS_GONE_MS = 2400;
// The row's own entrance and exit (scene-loops.css).
const ROW_MOTION_MS = 260;

/** The app's formatUptime: "just started", "47m", "3h 12m", "2d 4h". */
function formatUptime(seconds: number): string {
  if (seconds < 60) return "just started";
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `${minutes}m`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return minutes % 60 ? `${hours}h ${minutes % 60}m` : `${hours}h`;
  const days = Math.floor(hours / 24);
  return hours % 24 ? `${days}d ${hours % 24}h` : `${days}d`;
}

/**
 * PortRow inside PortList: the port, its name and framework, then how it runs
 * and for how long (describePort), with NativeOpenLink and StopServiceButton.
 * The services started outside any session, so they share one group, which
 * needs no header, and with three rows the list offers no filter.
 */
function PortRow({ entry, motion }: { entry: PortService; motion?: "in" | "out" }) {
  const info = `${entry.name} · project name · ${entry.process} · PID ${entry.pid}\nThis device only`;
  const stop = `Stop PID ${entry.pid}`;
  return (
    <div className={`port-row${motion ? ` pz-row-${motion}` : ""}`} title={info}>
      <span className="port-num">{entry.port}</span>
      <div className="port-main">
        <div className="port-line">
          <span className="port-title">{entry.name}</span>
          {entry.kind ? <span className="port-kind">{entry.kind}</span> : null}
        </div>
        <div className="port-meta">
          <span>{entry.process}</span>
          <span title="How long it has been running">{formatUptime(entry.uptime)}</span>
        </div>
      </div>
      <div className="port-actions">
        <button type="button" className="tile-btn async-button" title={`Open localhost:${entry.port}`} aria-label={`Open localhost:${entry.port}`} aria-busy={false}>
          <span className="async-button-icon" style={{ width: 13, height: 13 }} aria-hidden="true">
            <ExternalLink size={13} strokeWidth={2} />
          </span>
        </button>
        <button type="button" className="tile-btn tile-btn-danger" title={stop} aria-label={`${stop} on port ${entry.port}`}>
          <CircleStop size={13} />
        </button>
      </div>
    </div>
  );
}

/**
 * The Port manager dropdown (PortsMenu with TauriPorts, as the desktop app
 * shows it): Dropdown width 320, align end, compact.
 */
export function PortsPanel() {
  const panel = useRef<HTMLDivElement>(null);
  const [docs, setDocs] = useState<"in" | "out" | null>(null);
  usePanelLoop(panel, async (wait) => {
    await wait(PORTS_REST_MS);
    setDocs("in");
    await wait(PORTS_UP_MS);
    setDocs("out");
    await wait(ROW_MOTION_MS);
    setDocs(null);
    await wait(PORTS_GONE_MS - ROW_MOTION_MS);
  });
  // The list is sorted by port, so the docs server lands between the two.
  const rows = [...FORWARDED, ...(docs ? [DOCS_SERVER] : [])].sort((a, b) => a.port - b.port);
  const forwarded = docs === "in" ? rows.length : FORWARDED.length;
  return (
    <div ref={panel} className="menu menu-panel menu-compact" style={{ right: PANEL.ports, top: PANEL.top, left: "auto", width: 320 }}>
      <div className="menu-body">
        <div className="menu-head-title">Port manager</div>
        <div className="ports-tabs" role="tablist" aria-label="Port views">
          <div className="usage-seg" role="group">
            <button type="button" role="tab" aria-selected={true} className="on">
              Forwarded
            </button>
            <button type="button" role="tab" aria-selected={false} className="">
              This device
            </button>
          </div>
        </div>
        <section className="ports-menu-services" aria-label="Forwarded services">
          <div className="settings-row ports-status">
            <span className="ports-route-inline">
              {DEVBOX.name} → {THIS_MAC.name}
            </span>
            <span className="dot dot-up" />
            <span className="small muted ports-status-text" role="status">
              forwarding {forwarded} ports
            </span>
            <div className="ports-status-spacer" />
          </div>
          <div className="ports-box">
            <section className="ports-group" aria-label="Other services">
              {rows.map((entry) => (
                <PortRow key={entry.port} entry={entry} motion={entry === DOCS_SERVER && docs ? docs : undefined} />
              ))}
            </section>
          </div>
        </section>
        <button type="button" className="menu-item">
          <Settings size={16} strokeWidth={1.9} />
          Settings
        </button>
      </div>
    </div>
  );
}

