/** An approval prompt still waiting, as PermissionNoticeActions shows it. */
interface Approval {
  subject: string;
  choices: { label: string; shortLabel: string; role: "allow" | "allow-always" | "deny" | "deny-feedback" }[];
}

interface Notice {
  /** The session's name (or a part of the app) the notice comes from. */
  source?: string;
  /** The session's device (noticeDeviceFor); This Device in these scenes. */
  device?: string;
  title: string;
  body: string;
  category: "terminal" | "sync" | "app";
  /** ISO timestamp and the en-US toLocaleString() text the row prints. */
  at: string;
  shown: string;
  read: boolean;
  review?: boolean;
  related: boolean;
  approval?: Approval;
}

// Newest first, with the prompt still waiting for approval on top: Claude
