// With no query the palette lists every row, its groups in this order.
const RESTING_ORDER = ["Sessions", "Workspaces", "Actions", "Recent folders", "Help"];
const RESTING = RESTING_ORDER.map((group) => ({ group, rows: PALETTE_ITEMS.filter((entry) => entry.group === group) }));

// The loop: two searches a visitor would make, typed at a steady pace, with
// the highlight stepping down to the second result of the first; each query
// is then deleted back to the resting list.
const PALETTE_QUERIES: { text: string; moves: number }[] = [
  { text: "broad", moves: 1 },
  { text: "max", moves: 0 },
];
const PALETTE_REST_MS = 2200;
const PALETTE_KEY_MS = 120;
const PALETTE_ERASE_MS = 45;
const PALETTE_LOOK_MS = 900;
const PALETTE_HOLD_MS = 1800;
const PALETTE_BETWEEN_MS = 1100;

export function PaletteShot() {
  const listId = useId();
  const dialog = useRef<HTMLDivElement>(null);
  const [query, setQuery] = useState("");
  const [cursor, setCursor] = useState(0);
  usePanelLoop(
    dialog,
    async (wait) => {
      await wait(PALETTE_REST_MS);
      for (const [n, { text, moves }] of PALETTE_QUERIES.entries()) {
        if (n > 0) await wait(PALETTE_BETWEEN_MS);
        // Every keystroke resets the highlight to the best match, as in the app.
        for (let i = 1; i <= text.length; i += 1) {
          setQuery(text.slice(0, i));
          setCursor(0);
          await wait(PALETTE_KEY_MS);
        }
        await wait(PALETTE_LOOK_MS);
        for (let step = 1; step <= moves; step += 1) {
          setCursor(step);
          await wait(PALETTE_LOOK_MS);
        }
        await wait(PALETTE_HOLD_MS);
        for (let i = text.length - 1; i >= 0; i -= 1) {
          setQuery(text.slice(0, i));
          setCursor(0);
          await wait(PALETTE_ERASE_MS);
        }
      }
    },
    () => {
      setQuery("");
      setCursor(0);
    },
  );

  // At rest every row in the app's group order; a query ranks them like the app.
  const groups: { group: string; rows: { row: PaletteItem; positions: number[] }[] }[] = query
    ? searchPalette(PALETTE_ITEMS, query).map(({ group, rows }) => ({ group, rows: rows.map(({ item: row, positions }) => ({ row, positions })) }))
    : RESTING.map(({ group, rows }) => ({ group, rows: rows.map((row) => ({ row, positions: [] })) }));
  const total = groups.reduce((sum, { rows }) => sum + rows.length, 0);
  const current = Math.min(cursor, total - 1);
  let index = 0;

  // The close-up in a small card; the whole 600px palette in a wider one.
  const cardWidth = useCardWidth(dialog);
  const wide = cardWidth !== null && cardWidth > CLOSE.width;
  const frame = wide ? PALETTE_WIDE : CLOSE;

  // The list scrolls inside the room the dialog leaves it (at most 380px, the
  // app's max-height), and stops after its last whole row, so no row shows
  // half cut by the scroll box. Not after its bottom padding: the next row
  // would show through it.
  const list = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    const element = list.current;
    if (!element) return;
    element.style.maxHeight = "";
    if (element.scrollHeight <= element.clientHeight) return;
    const box = element.getBoundingClientRect();
    const scale = box.height / element.offsetHeight || 1;
    const bottoms = [...element.querySelectorAll<HTMLElement>(".cmdk-row")]
      .map((row) => (row.getBoundingClientRect().bottom - box.top) / scale + element.scrollTop)
      .filter((bottom) => bottom <= element.clientHeight);
    if (bottoms.length) element.style.maxHeight = `${Math.max(...bottoms)}px`;
  }, [query, wide]);

  // The palette is a modal: the app's .cmdk-backdrop pads the window and the
  // dialog takes at most the room left (max-width and max-height 100%). Here
  // a box inset in the card plays the backdrop; the close-up squeezes the
  // dialog into the small card as a narrow window would.
  return (
    <Shot id="palette" width={frame.width} height={frame.height}>
      <div style={{ position: "absolute", inset: wide ? "26px 20px" : 14 }}>
        <div ref={dialog} className="cmdk" role="dialog" aria-modal="true" aria-label="Command palette" tabIndex={-1} style={{ position: "absolute", left: 0, top: 0 }}>
          <div className="cmdk-search">
            <Search size={16} strokeWidth={1.9} aria-hidden="true" />
            <input
              className="cmdk-input"
              value={query}
              placeholder="Search actions, sessions, workspaces and help"
              spellCheck={false}
              autoComplete="off"
              role="combobox"
              aria-expanded="true"
              aria-controls={listId}
              aria-autocomplete="list"
              aria-label="Search commands"
              aria-activedescendant={total ? `${listId}-${current}` : undefined}
              readOnly
            />
            <kbd className="kbd" aria-hidden="true">
              ⌘K
            </kbd>
          </div>
          <div ref={list} className="cmdk-list" id={listId} role="listbox" aria-label="Commands">
            {groups.map(({ group, rows }) => (
              <div className="cmdk-group" role="group" aria-label={group} key={group}>
                <div className="cmdk-group-title" aria-hidden="true">
                  {group}
                </div>
                {rows.map(({ row, positions }) => {
                  const at = index++;
                  const selected = at === current;
                  return (
                    <div key={row.label} id={`${listId}-${at}`} role="option" aria-selected={selected} className={`cmdk-row ${selected ? "cmdk-row-active" : ""}`}>
                      {row.icon}
                      <span className="cmdk-row-label">
                        <Highlight text={row.label} positions={positions} />
                      </span>
                      <span className="cmdk-row-detail">{row.detail}</span>
                      {row.shortcut ? (
                        <kbd className="kbd" aria-hidden="true">
                          {row.shortcut}
                        </kbd>
                      ) : null}
                    </div>
                  );
                })}
              </div>
            ))}
            {!total ? (
              <div className="cmdk-empty" role="status">
                <Search size={15} aria-hidden="true" />
                <span>Nothing matches “{query.trim()}”.</span>
              </div>
            ) : null}
          </div>
          <div className="cmdk-foot" aria-hidden="true">
            <span>
              <kbd className="kbd">↑</kbd>
              <kbd className="kbd">↓</kbd> move
            </span>
            <span>
              <kbd className="kbd">↵</kbd> run
            </span>
            <span>
              <kbd className="kbd">esc</kbd> close
            </span>
          </div>
        </div>
      </div>
    </Shot>
  );
}

/* ======================================================= agent usage ===== */

// The app's formatters (src/panels/UsageSpend.tsx).
function fmtCost(c: number): string {
  if (c >= 1000) return `$${(c / 1000).toFixed(1)}K`;
  if (c >= 100) return `$${Math.round(c).toLocaleString("en-US")}`;
  return `$${c.toFixed(2)}`;
}

function fmtTokens(n: number): string {
  if (n >= 1e9) return `${(n / 1e9).toFixed(1)}B`;
  if (n >= 1e6) return `${(n / 1e6).toFixed(1)}M`;
  if (n >= 1e3) return `${(n / 1e3).toFixed(1)}K`;
  return `${Math.round(n)}`;
}

interface SpendDay {
  day: string;
  tokens: number;
  cost: number;
}

interface Spend {
  days: SpendDay[];
  /** Cost the agent stored itself (OpenCode) rather than a rate estimate. */
  recorded: boolean;
}

/** Thirty days ending today, from millions of tokens per day and a blended $/M rate. */
function spendOf(millions: number[], rate: number, recorded = false): Spend {
  const today = Date.UTC(2026, 10, 11);
  return {
    recorded,
    days: millions.map((m, i) => ({
      day: new Date(today - (millions.length - 1 - i) * 86_400_000).toISOString().slice(0, 10),
      tokens: m * 1e6,
      cost: m * rate,
    })),
  };
}

const CLAUDE_SPEND = spendOf(
  [18.2, 22.5, 9.1, 0, 0, 25.4, 31.2, 28.7, 19.9, 24.1, 6.3, 0, 27.8, 35.6, 30.2, 22.4, 26.9, 4.8, 2.1, 29.3, 33.8, 38.1, 27.5, 31.9, 8.4, 0, 34.2, 40.6, 36.3, 21.7],
  0.58,
);
const CODEX_SPEND = spendOf(
  [4.1, 6.8, 0, 0, 2.2, 7.4, 5.9, 8.8, 3.1, 0, 0, 6.2, 9.4, 7.7, 5.1, 4.6, 0, 1.3, 8.1, 10.2, 6.6, 7.9, 2.4, 0, 9.8, 11.3, 8.7, 6.1, 4.4, 5.2],
  0.41,
);
const OPENCODE_SPEND = spendOf(
  [0, 0.4, 0.6, 0, 0, 0.3, 0.8, 0.5, 0, 0, 0, 0.7, 0.9, 0.2, 0, 0.4, 0, 0, 0.6, 1.1, 0.5, 0.3, 0, 0, 0.8, 0.6, 0.4, 0.2, 0, 0.3],
  0.71,
  true,
);

function windowOf(days: SpendDay[]): { tokens: number; cost: number } {
  return days.reduce((sum, day) => ({ tokens: sum.tokens + day.tokens, cost: sum.cost + day.cost }), { tokens: 0, cost: 0 });
}

/** UsageSpend: the "More" details of a card, or an Other agents row with `summary`. */
function UsageSpend({ spend, color, summary, agentName }: { spend: Spend; color: string; summary?: ReactNode; agentName: string }) {
  const { recorded, days } = spend;
  const row = (label: string, w: { tokens: number; cost: number }) => (
    <div className="usage-detail-row">
      <span className="usage-detail-label">{label}</span>
      <span className="usage-detail-val" title={fmtCost(w.cost)}>
        <b>{fmtCost(w.cost)}</b> · {fmtTokens(w.tokens)} tokens
      </span>
    </div>
  );
  const max = Math.max(...days.map((day) => day.tokens), 1);
  const source = `${agentName}'s`;
  return (
    <div
      className={`usage-detail${summary ? " usage-detail-row-only" : ""}`}
      title={
        recorded
          ? `Cost from ${source} local session records.`
          : "Standard short-context API-equivalent estimates from local token counts. Long-context and service-tier adjustments are not included."
      }
    >
      <details className="usage-more-details">
        <summary>{summary ?? "More"}</summary>
        <p className="usage-estimate-note" role="note">
          <Info size={12} aria-hidden="true" />
          <span>{recorded ? `Cost recorded in ${source} own session data, not an estimate.` : "API estimate (short context), not billed spend."}</span>
        </p>
        <div className="usage-detail-row">
          <span className="usage-detail-label">Token trend</span>
          <div
            className="usage-trend"
            role="img"
            aria-label="Daily token usage, last 30 days. Bar height represents tokens, not cost; pricing availability does not affect the bars."
          >
            {days.map((day) => (
              <span
                key={day.day}
                className="usage-trend-bar"
                style={{ height: `${day.tokens > 0 ? Math.max(2, Math.round((day.tokens / max) * 100)) : 0}%`, background: color }}
                title={`${day.day} · ${fmtTokens(day.tokens)} tokens · ${fmtCost(day.cost)}`}
              />
            ))}
          </div>
        </div>
        <details className="usage-daily-details">
          <summary>Daily breakdown</summary>
          <div className="usage-daily-scroll">
            <table>
              <caption>{`Daily token usage and ${recorded ? "recorded cost" : "API-equivalent estimates"}`}</caption>
              <thead>
                <tr>
                  <th scope="col">Day</th>
                  <th scope="col">Tokens</th>
                  <th scope="col">{recorded ? "Cost" : "Estimate"}</th>
                </tr>
              </thead>
              <tbody>
                {days.map((day) => (
                  <tr key={day.day}>
                    <th scope="row">{day.day}</th>
                    <td>{fmtTokens(day.tokens)}</td>
                    <td title={fmtCost(day.cost)}>{fmtCost(day.cost)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </details>
        <div className="usage-detail-rows">
          {row("Today", days[days.length - 1])}
          {row("Yesterday", days[days.length - 2])}
          {row("Last 30 days", windowOf(days))}
        </div>
      </details>
    </div>
  );
}

/** Colour by how much is used (the risk), whatever the number shows. */
function barColor(used: number): string {
  if (used >= 90) return "#e5484d";
  if (used >= 70) return "#d9a441";
  return "#5fb37f";
}

interface LimitBar {
  label: string;
  used: number;
  /** fmtReset, fmtResetShort and fmtResetAbs of the reset time. */
  reset: string;
  short: string;
  abs: string;
  /** The row the top bar shows automatically (the highest usage). */
  auto?: boolean;
}

type UsageModeName = "left" | "used";

/** The app's Bar for one limit window, with its menu bar pin (never pinned here). */
function Bar({ bar, account, mode }: { bar: LimitBar; account: string; mode: UsageModeName }) {
  const shown = mode === "used" ? bar.used : 100 - bar.used;
  const full = `${bar.label} ${shown}% ${mode} · resets in ${bar.reset} (${bar.abs})`;
  return (
    <div className="usage-bar-row">
      <div className="usage-bar-top">
        <span className="usage-bar-text" title={full}>
          <span className="usage-bar-label">{bar.label}</span>
          <span className="usage-bar-pct">{shown}%</span>
          <span className="usage-bar-reset">
            · {bar.reset} <span className="usage-bar-reset-abs">{bar.short}</span>
          </span>
        </span>
        <button
          type="button"
          className={`usage-pin  ${bar.auto ? "is-auto" : ""}`}
          aria-pressed={false}
          aria-label={`Show ${account} ${bar.label} in the menu bar`}
          title={bar.auto ? "Shown in the menu bar automatically (highest usage). Click to keep showing this one" : "Show this limit in the menu bar"}
        >
          {bar.auto ? <span className="usage-pin-auto">Auto</span> : null}
          <span className="usage-radio" aria-hidden="true" />
        </button>
      </div>
      <div className="usage-bar">
        <div className="usage-bar-fill" style={{ width: `${shown}%`, background: barColor(bar.used) }} />
      </div>
    </div>
  );
}

