type UsageCard = (typeof USAGE_CARDS)[number];

// A refresh a minute later, while the agents kept working: the 5h windows
// moved up and their resets came a minute closer; the weekly ones held.
const USAGE_LATER: Record<string, Pick<LimitBar, "used" | "reset">> = {
  "Claude 5h": { used: 40, reset: "2h 13m" },
  "Codex 5h": { used: 14, reset: "4h 39m" },
};
const refreshedCards = (cards: UsageCard[]): UsageCard[] =>
  cards.map((card) => ({ ...card, bars: card.bars.map((bar) => ({ ...bar, ...USAGE_LATER[`${card.name} ${bar.label}`] })) }));

