/** The Agent usage dropdown: Dropdown width 320, align start (clamped to the window edge). */
export function UsagePanel({
  anchor,
  cards = USAGE_CARDS,
  mode: shownMode,
  refreshing = false,
  panelRef,
}: {
  anchor?: CSSProperties;
  cards?: UsageCard[];
  /** The mode a loop shows; the visitor's choice otherwise. */
  mode?: UsageModeName;
  refreshing?: boolean;
  panelRef?: RefObject<HTMLDivElement>;
}) {
  const [picked, setPicked] = useState<UsageModeName>("left");
  return (
    <div ref={panelRef} className="menu menu-panel" style={{ width: 320, ...(anchor ?? { right: PANEL.edge, top: PANEL.top, left: "auto" }) }}>
      <UsageBody cards={cards} mode={shownMode ?? picked} onMode={setPicked} refreshing={refreshing} />
    </div>
  );
}

// The loop: Used shows what is spent, Refresh (one turn of its icon, as the
// app lets the spin finish) brings the latest numbers, and Left comes back
// as the round starts over.
const USAGE_REST_MS = 2400;
const USAGE_MODE_MS = 1300;
const USAGE_SPIN_MS = 900;
const USAGE_READ_MS = 2800;
const USAGE_BACK_MS = 2200;

export function UsageShot() {
  const panel = useRef<HTMLDivElement>(null);
  const [later, setLater] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  // The loop's Left / Used; null once the visitor has the switch.
  const [mode, setMode] = useState<UsageModeName | null>("left");
  usePanelLoop(
    panel,
    async (wait) => {
      await wait(USAGE_REST_MS);
      setMode("used");
      await wait(USAGE_MODE_MS);
      setRefreshing(true);
      await wait(USAGE_SPIN_MS);
      setRefreshing(false);
      setLater(true);
      await wait(USAGE_READ_MS);
      setMode("left");
      setLater(false);
      await wait(USAGE_BACK_MS);
    },
    () => {
      setRefreshing(false);
      setMode(null);
    },
  );
  return (
    <Shot id="usage" width={USAGE.width} height={USAGE.height}>
      <UsagePanel
        panelRef={panel}
        anchor={{ left: (USAGE.width - 320) / 2, top: 28 }}
        cards={later ? refreshedCards(USAGE_CARDS) : USAGE_CARDS}
        mode={mode ?? undefined}
        refreshing={refreshing}
      />
    </Shot>
  );
}

/* ======================================================== workspaces ===== */

// The tab indexes of WorkspaceTabs: All (⌥0) and fieldnotes (⌥1).
const ALL_TAB = 0;
const FIELDNOTES_TAB = 1;

// The loop: ⌥0 shows every workspace's sessions, ⌥1 goes back to fieldnotes.
const SPACES_REST_MS = 3200;
const SPACES_ALL_MS = 3600;

/** A captured session tile of the workspaces scene, `span` grid tracks wide
    (Canvas.tsx gives each tile its track span). */
function SpaceTile({ title, capture, kbd, stat, span }: { title: string; capture: CaptureId; kbd: string; stat?: "notify"; span?: number }) {
  return (
    <Tile title={title} agent="claude" kbd={kbd} stat={stat} device={THIS_MAC} style={span ? { gridColumn: `span ${span}` } : undefined}>
      <Term>
        <AnsiScreen id={capture} />
      </Term>
    </Tile>
  );
}

/* The workspaces window, 1440 x 900 (its size on a 1080p display), shows
   three columns of tiles: fieldnotes' three sessions, or All's five in two
   rows of three and two (the app's automatic layout for five). Its framings
   only cut the window in the gaps between those columns (the canvas's 10px
   padding and gaps put them at x 476.7 to 486.7 and 953.3 to 963.3) and
   between two terminal rows of the top tiles (their rows sit on a 15px grid
   from y 89), above the second row of All (from y 476). */
const SPACES_WINDOW = { width: 1440, height: 900 };
const SPACES_COLUMN = (SPACES_WINDOW.width - 40) / 3;
/** The middle of the gap between the first and second columns. */
const SPACES_GAP = 10 + SPACES_COLUMN + 5;
/** The small card: the middle column under the tab strip, gap to gap, in the
    small cards' shape; the window's y 419 ends it. */
const SPACES_CLOSE = { width: SPACES_COLUMN + 10, height: 442, top: 23 };
/** A card wider than that (a docs page): the window's right two columns from
    the same gap, with the tools, down to y 464. */
const SPACES_WIDE = { width: SPACES_WINDOW.width + 16 - SPACES_GAP, height: 488, top: 24 };

/**
 * Workspaces: the workspace tabs in the middle of the top bar and the tiles
 * under them. fieldnotes holds api, web and docs in three columns (its own
 * column setting); All adds personal's release (the session waiting on the
 * visitor) and guide, in the app's one tile order, and lays the five out in
 * rows of three and two, as the app's automatic layout does. The top row's
 * tiles are as wide as fieldnotes' columns, so the captures fit them both.
 */
export function WorkspacesShot() {
  const windowRef = useRef<HTMLElement>(null);
  const [tab, setTab] = useState(FIELDNOTES_TAB);
  // Set after the first switch, so the canvas fades in on a swap but not on load.
  const [switched, setSwitched] = useState(false);
  usePanelLoop(windowRef, async (wait) => {
    await wait(SPACES_REST_MS);
    setSwitched(true);
    setTab(ALL_TAB);
    await wait(SPACES_ALL_MS);
    setTab(FIELDNOTES_TAB);
  });
  const cardWidth = useCardWidth(windowRef);
  const frame = cardWidth !== null && cardWidth > SPACES_CLOSE.width ? SPACES_WIDE : SPACES_CLOSE;
  const all = tab === ALL_TAB;
  return (
    <Shot id="spaces" width={frame.width} height={frame.height} className={switched ? "pz-spaces-swapped" : ""}>
      <Window style={{ left: -SPACES_GAP, top: frame.top, ...SPACES_WINDOW }}>
        <TopBar>
          <Brand />
          <WorkspaceTabs active={tab} />
          <ToolsBar panels={{}} />
        </TopBar>
        <ActiveCanvas
          canvasRef={windowRef}
          // A new canvas per workspace, as the app shows another set of tiles.
          key={tab}
          style={all ? { gridTemplateColumns: "repeat(6, minmax(0, 1fr))", gridTemplateRows: "1fr 1fr" } : { gridTemplateColumns: "1fr 1fr 1fr" }}
          tiles={
            all
              ? [
                  <SpaceTile key="api" title="api" capture="api-57" kbd="⌘1" span={2} />,
                  <SpaceTile key="release" title="release" capture="release-57" kbd="⌘2" stat="notify" span={2} />,
                  <SpaceTile key="web" title="web" capture="web-57" kbd="⌘3" span={2} />,
                  <SpaceTile key="docs" title="docs" capture="docs-86" kbd="⌘4" span={3} />,
                  <SpaceTile key="guide" title="guide" capture="docs-86" kbd="⌘5" span={3} />,
                ]
              : [
                  <SpaceTile key="api" title="api" capture="api-57" kbd="⌘1" />,
                  <SpaceTile key="web" title="web" capture="web-57" kbd="⌘2" />,
                  <SpaceTile key="docs" title="docs" capture="docs-57" kbd="⌘3" />,
                ]
          }
        />
      </Window>
    </Shot>
  );
}
